+# Stage 2 from the official World Mirror recipe: freeze the stage-1 modules
+# and train the Gaussian head. Load weights with pretrained. Do not resume
+# the stage-1 optimizer. gsplat rendering stays float32 inside World Mirror.
+worldmirror:
+  repo_path: ${WORLD_MIRROR_PATH:}
+  hydra_config: stage2.yaml
+  attention_backend: aiter
+  hypersim_dir: ${HYPERSIM_DIR:/shared_nfs/3dwm/hywm-3dwm-sub20/hypersim}
